// В политике продукт подставляется токеном {{PRODUCT}} → «гайд» / «курс».
const fillProduct = (text, product) => text.split('{{PRODUCT}}').join(product);

export const buildPrivacy = (product) => ({
  title: PRIVACY.title,
  updated: PRIVACY.updated,
  intro: fillProduct(PRIVACY.intro, product),
  sections: PRIVACY.sections.map((s) => ({
    heading: s.heading,
    paragraphs: s.paragraphs.map((p) => fillProduct(p, product)),
  })),
});

